query:
INSERT INTO staffDepartments (organizationId, name, description, createdBy, updatedBy)
SELECT g.id, CONCAT(g.name, ' Department'), CONCAT('Default department for ', g.name), g.createdBy, g.updatedBy
FROM `groups` g;

